            allowed = set(str(x) for x in r["allowed"])
            for m in re.finditer(r"(?<![A-Za-z0-9.])\d[\d,]*(?:\.\d+)?%?", b):
                tok = m.group(0).rstrip(",").replace(",", "")
                if tok not in allowed and tok.rstrip("%") not in allowed:
                    fails.append(f"number {tok!r} does not appear in the source material")
                    break
        elif t == "json_file":
            pass
        else:
            fails.append(f"unknown rule {t}")
    if extra_fn:
        try:
            fails.extend(extra_fn(text))
        except Exception as e:
            fails.append(f"extra check raised {type(e).__name__}: {e}")
    return fails



import re
MENU = [('cheese wedge', 70, 280, 260, 'protein'), ('energy gel', 40, 100, 220, 'carb'), ('oat bars', 60, 240, 150, 'carb'), ('apple chips', 30, 110, 200, 'fruit'), ('peanut butter pouch', 45, 270, 190, 'protein'), ('trail mix', 100, 520, 280, 'carb'), ('jerky', 50, 130, 420, 'protein'), ('instant noodles', 85, 380, 120, 'carb'), ('dark chocolate', 100, 540, 240, 'treat'), ('tuna pouch', 80, 120, 230, 'protein')]
W, CMIN, B, MAXQ = 525, 1850, 2165, 2
NEED_PROT = True
MIN_ITEMS = 5


def extra(text):
    fails = []
    got = {}
    for ln in text.splitlines():
        if not ln.strip():
            continue
        m = re.match(r"^\s*[-*]?\s*(.+?)\s*[x\u00d7]\s*(\d+)\s*$", ln)
        if not m:
            fails.append("line not in the form 'item x N': " + ln[:50])
            continue
        nm, q = m.group(1).strip().lower(), int(m.group(2))
        names = {it[0]: it for it in MENU}
        if nm not in names:
            fails.append("unknown item: " + nm)
            continue
        got[nm] = got.get(nm, 0) + q
    w = sum(q * [it for it in MENU if it[0] == nm][0][1] for nm, q in got.items() if any(it[0] == nm for it in MENU))
    cal = sum(q * [it for it in MENU if it[0] == nm][0][2] for nm, q in got.items() if any(it[0] == nm for it in MENU))
    cost = sum(q * [it for it in MENU if it[0] == nm][0][3] for nm, q in got.items() if any(it[0] == nm for it in MENU))
    if w > W:
        fails.append(f"weight {w} g exceeds {W} g")
    if cal < CMIN:
        fails.append(f"energy {cal} kcal is below {CMIN} kcal")
    if cost > B:
        fails.append(f"price {cost} exceeds {B}")
    if any(q > MAXQ or q < 1 for q in got.values()):
        fails.append("quantities must be between 1 and " + str(MAXQ))
    if NEED_PROT and not any([it for it in MENU if it[0] == nm][0][4] == "protein" for nm in got if any(it[0] == nm for it in MENU)):
        fails.append("no protein item")
    if sum(got.values()) < MIN_ITEMS:
        fails.append("too few items")
    return fails



def main():
    p = Path(TARGET)
    if not p.exists():
        print(f"FAIL: {TARGET} does not exist")
        return 1
    text = p.read_text(encoding="utf-8", errors="replace")
    if not text.strip():
        print(f"FAIL: {TARGET} is empty")
        return 1
    fails = run_checks(RULES, text, globals().get("extra"))
    if fails:
        print("FAIL:")
        for f in fails:
            print(" -", f)
        return 1
    print("OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
